class DynamicArray:
    """动态数组：容量不够时按 2 倍扩容。"""

    def __init__(self):
        self._data = [None] * 2
        self._size = 0

    def append(self, value):
        if self._size == len(self._data):
            self._grow()
        self._data[self._size] = value
        self._size += 1

    def _grow(self):
        new_data = [None] * (len(self._data) * 2)
        for i, v in enumerate(self._data):
            new_data[i] = v
        self._data = new_data
        print("扩容到", len(self._data))

    def __len__(self):
        return self._size

arr = DynamicArray()
for i in range(5):
    arr.append(i)
print("元素数:", len(arr))

def dedup_sorted(arr):
    if not arr:
        return []
    slow = 0
    for fast in range(1, len(arr)):
        if arr[fast] != arr[slow]:
            slow += 1
            arr[slow] = arr[fast]
    return arr[:slow + 1]

print(dedup_sorted([1, 1, 2, 3, 3, 3, 4]))

def remove_val(arr, val):
    write = 0
    for read in range(len(arr)):
        if arr[read] != val:
            arr[write] = arr[read]
            write += 1
    return arr[:write]

print(remove_val([3, 1, 3, 2, 3], 3))

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

print(binary_search([1, 3, 5, 7, 9], 7))
print(binary_search([1, 3, 5], 4))

def prefix_sums(arr):
    pre = [0]
    for v in arr:
        pre.append(pre[-1] + v)
    return pre

def range_sum(pre, i, j):
    return pre[j + 1] - pre[i]

pre = prefix_sums([2, 4, 6, 8])
print(range_sum(pre, 1, 3))
